export default JSON.parse("{\"schema\":\"ai-brain.semantic-merge.v1\",\"id\":\"improving-the-moment-a-way-to-remember-these-skills-is-the-word-improve-with-ima-23ff248eefc6\",\"title\":\"Improving the Moment A way to remember these skills is the word IMPROVE. With Imagery: \\u0003\",\"domain\":\"dbt\",\"relatedDomains\":[\"dbt\"],\"purpose\":\"handout\",\"capabilities\":[\"dbt\",\"reference\",\"research\"],\"similarityReview\":{\"threshold\":0.75,\"pairScores\":[0.979],\"method\":\"5-token shingle Jaccard within same explicit purpose/title context\"},\"provenance\":{\"mergePolicy\":\"shared structure/content consolidated; unique list items/fields retained; scalar conflicts retained as _merged_values\",\"sources\":[{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/05-dbt-distress-tolerance-distress-tolerance-handout-9-improving-the-moment-a-way-to-remembe-1a5f94066d.json\",\"sha256\":\"1a5f94066df3c97daeb58f67b1912621b47f35705f72fb5ab3defdfb3a73210a\",\"domain\":\"dbt\",\"bytes\":7461},{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/distress-tolerance-handout-9-improving-the-moment-a-way-to-remember-these-skills-is-the-word-91d0e9e1fd.json\",\"sha256\":\"91d0e9e1fd1ff769fde2651fa7c4ede71f3d6351be702a874b6dd6903e66795b\",\"domain\":\"dbt\",\"bytes\":7301}]},\"data\":{\"pages\":[{\"pdf_page\":360,\"book_page\":\"336\",\"text\":\"336\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\n\u00ab\\nDistress Tolerance Handout 9   (Distress Tolerance Worksheets 7\u20137b)\\nImproving the Moment\\nA way to remember these skills is the word IMPROVE.\\nWith Imagery:\\n\\u0003\\n\u0089 Imagine very relaxing scenes.\\n\\u0003\\n\u0089 Imagine a secret room within yourself. Furnish\\nit the way you like. Close and lock the door on\\nanything that can hurt you.\\n\\u0003\\n\u0089 Imagine everything going well.\\n\\u0003\\n\u0089 Make up a calming fantasy world.\\n\\u0003\\n\u0089 Imagine hurtful emotions draining out of you\\nlike water out of a pipe.\\n\\u0003\\n\u0089 Remember a happy time and imagine yourself\\nin it again; play out the time in your mind\\nagain.\\n\\u0003\\n\u0089 Other:\\nWith Meaning:\\n\\u0003\\n\u0089 Find purpose or meaning in a painful situation.\\n\\u0003\\n\u0089 Focus on whatever positive aspects of a\\npainful situation you can find.\\n\\u0003\\n\u0089 Repeat these positive aspects in your mind.\\n\\u0003\\n\u0089 Remember, listen to, or read about spiritual\\nvalues.\\n\\u0003\\n\u0089 Other:\\nWith Prayer:\\n\\u0003\\n\u0089 Open your heart to a supreme being, God, or\\nyour own Wise Mind.\\n\\u0003\\n\u0089 Ask for strength to bear the pain.\\n\\u0003\\n\u0089 Turn things over to God or a higher being.\\n\\u0003\\n\u0089 Other:\\nWith Relaxing actions:\\n\\u0003\\n\u0089 Take a hot bath or sit in a hot tub.\\n\\u0003\\n\u0089 Drink hot milk.\\n\\u0003\\n\u0089 Massage your neck and scalp.\\n\\u0003\\n\u0089 Practice yoga or other stretching.\\n\\u0003\\n\u0089 Breathe deeply.\\n\\u0003\\n\u0089 Change your facial expression.\\n\\u0003\\n\u0089 Other:\\nWith One thing in the moment:\\n\\u0003\\n\u0089 Focus your entire attention on just what you\\nare doing.\\n\\u0003\\n\u0089 Keep yourself in the moment.\\n\\u0003\\n\u0089 Put your mind in the present.\\n\\u0003\\n\u0089 Focus your entire attention on the physical\\n\\u0003\\n\u0089 Listen to a sensory awareness recording (or\\nuse Distress Tolerance Handout 9a)\\n\\u0003\\n\u0089 Other:\\nWith a brief Vacation:\\n\\u0003\\n\u0089 Give yourself a brief vacation.\\n\\u0003\\n\u0089 Get in bed; pull the covers up over your head.\\n\\u0003\\n\u0089 Go to the beach or the woods for the day.\\n\\u0003\\n\u0089 Get a magazine and read it with chocolates.\\n\\u0003\\n\u0089 Turn off your phone for a day.\\n\\u0003\\n\u0089 Take a blanket to the park and sit on it for a\\nwhole afternoon.\\n\\u0003\\n\u0089 Take a 1-hour breather from hard work.\\n\\u0003\\n\u0089 Take a brief vacation from responsibility.\\n\\u0003\\n\u0089 Other:\\nWith self-Encouragement and rethinking the situation:\\n\\u0003\\n\u0089 Cheerlead yourself: \u201cYou go, girl!\u201d \u201cYou da\\nman!\u201d\\n\\u0003\\n\u0089 \u201cI will make it out of this.\u201d\\n\\u0003\\n\u0089 \u201cI\u2019m doing the best I can.\u201d\\n\\u0003\\n\u0089 Repeat over and over: \u201cI can stand it.\u201d\\n\\u0003\\n\u0089 \u201cThis too shall pass.\u201d\\n\\u0003\\n\u0089 \u201cI will be OK.\u201d\\n\\u0003\\n\u0089 \u201cIt won\u2019t last forever.\u201d\\n\\u0003\\n\u0089 Other:\\nList (and then practice) rethoughts that are particularly important in your crisis situations (e.g., \u201cThe fact that he did\\nnot pick me up doesn\u2019t mean he doesn\u2019t love me\u201d):\\n\\u0003\\n\u0089\\n\\u0003\\n\u0089\"}],\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"source_marker\":\"Distress Tolerance Handout 9   (Distress Tolerance Worksheets 7\u20137b)\",\"source_pdf_pages\":[360],\"fillable_html_created\":false,\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/distress_tolerance/handouts/distress_tolerance_handout_9_improving_the_moment_a_way_to_remember_these_skills_is_the_word_improv.json\",\"item_number\":\"9\",\"full_text\":\"\u00ab\\nDistress Tolerance Handout 9   (Distress Tolerance Worksheets 7\u20137b)\\nImproving the Moment\\nA way to remember these skills is the word IMPROVE.\\nWith Imagery:\\n\\u0003\\n\u0089 Imagine very relaxing scenes.\\n\\u0003\\n\u0089 Imagine a secret room within yourself. Furnish\\nit the way you like. Close and lock the door on\\nanything that can hurt you.\\n\\u0003\\n\u0089 Imagine everything going well.\\n\\u0003\\n\u0089 Make up a calming fantasy world.\\n\\u0003\\n\u0089 Imagine hurtful emotions draining out of you\\nlike water out of a pipe.\\n\\u0003\\n\u0089 Remember a happy time and imagine yourself\\nin it again; play out the time in your mind\\nagain.\\n\\u0003\\n\u0089 Other:\\nWith Meaning:\\n\\u0003\\n\u0089 Find purpose or meaning in a painful situation.\\n\\u0003\\n\u0089 Focus on whatever positive aspects of a\\npainful situation you can find.\\n\\u0003\\n\u0089 Repeat these positive aspects in your mind.\\n\\u0003\\n\u0089 Remember, listen to, or read about spiritual\\nvalues.\\n\\u0003\\n\u0089 Other:\\nWith Prayer:\\n\\u0003\\n\u0089 Open your heart to a supreme being, God, or\\nyour own Wise Mind.\\n\\u0003\\n\u0089 Ask for strength to bear the pain.\\n\\u0003\\n\u0089 Turn things over to God or a higher being.\\n\\u0003\\n\u0089 Other:\\nWith Relaxing actions:\\n\\u0003\\n\u0089 Take a hot bath or sit in a hot tub.\\n\\u0003\\n\u0089 Drink hot milk.\\n\\u0003\\n\u0089 Massage your neck and scalp.\\n\\u0003\\n\u0089 Practice yoga or other stretching.\\n\\u0003\\n\u0089 Breathe deeply.\\n\\u0003\\n\u0089 Change your facial expression.\\n\\u0003\\n\u0089 Other:\\nWith One thing in the moment:\\n\\u0003\\n\u0089 Focus your entire attention on just what you\\nare doing.\\n\\u0003\\n\u0089 Keep yourself in the moment.\\n\\u0003\\n\u0089 Put your mind in the present.\\n\\u0003\\n\u0089 Focus your entire attention on the physical\\n\\u0003\\n\u0089 Listen to a sensory awareness recording (or\\nuse Distress Tolerance Handout 9a)\\n\\u0003\\n\u0089 Other:\\nWith a brief Vacation:\\n\\u0003\\n\u0089 Give yourself a brief vacation.\\n\\u0003\\n\u0089 Get in bed; pull the covers up over your head.\\n\\u0003\\n\u0089 Go to the beach or the woods for the day.\\n\\u0003\\n\u0089 Get a magazine and read it with chocolates.\\n\\u0003\\n\u0089 Turn off your phone for a day.\\n\\u0003\\n\u0089 Take a blanket to the park and sit on it for a\\nwhole afternoon.\\n\\u0003\\n\u0089 Take a 1-hour breather from hard work.\\n\\u0003\\n\u0089 Take a brief vacation from responsibility.\\n\\u0003\\n\u0089 Other:\\nWith self-Encouragement and rethinking the situation:\\n\\u0003\\n\u0089 Cheerlead yourself: \u201cYou go, girl!\u201d \u201cYou da\\nman!\u201d\\n\\u0003\\n\u0089 \u201cI will make it out of this.\u201d\\n\\u0003\\n\u0089 \u201cI\u2019m doing the best I can.\u201d\\n\\u0003\\n\u0089 Repeat over and over: \u201cI can stand it.\u201d\\n\\u0003\\n\u0089 \u201cThis too shall pass.\u201d\\n\\u0003\\n\u0089 \u201cI will be OK.\u201d\\n\\u0003\\n\u0089 \u201cIt won\u2019t last forever.\u201d\\n\\u0003\\n\u0089 Other:\\nList (and then practice) rethoughts that are particularly important in your crisis situations (e.g., \u201cThe fact that he did\\nnot pick me up doesn\u2019t mean he doesn\u2019t love me\u201d):\\n\\u0003\\n\u0089\\n\\u0003\\n\u0089\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"related_references\":[\"Distress Tolerance Worksheets 7\u20137b\"],\"id\":\"distress_tolerance_handout_9\",\"item_type\":\"handout\",\"is_example\":false,\"source_book_pages\":[\"336\"],\"title\":\"Improving the Moment A way to remember these skills is the word IMPROVE. With Imagery: \\u0003\",\"module_category\":\"Distress Tolerance Skills\",\"shared_json_path\":\"shared/05_dbt_distress_tolerance/handouts_json/distress_tolerance_handout_9_improving_the_moment_a_way_to_remember_these_406d3788.json\",\"module\":\"Distress Tolerance\",\"keywords\":[\"IMPROVE\",\"Imagery\",\"Improving\",\"Moment\",\"With\",\"remember\",\"skills\",\"these\",\"word\"]}}");
